def fixture(id,h0=0,pitch=0,roll=0,d=0,warp='rigid',kw=None,kr=0,rate=100000,offset_y=0):
    a=1.;bs=.75;bw=.5
    rails={}
    for axle,sx in [('front',-1),('rear',1)]:
        mean=h0+pitch*sx*a;slope=roll+sx*d/bs
        rails[axle]=dict(left=mean-bw*slope,right=mean+bw*slope)
    return dict(id=id,kind='synthetic_analytical_fixture_NOT_project_hardware',units='SI_m_N',
        geometry=dict(axle_half_spacing_m=a,spring_half_span_m=bs,wheel_contact_half_span_m=bw),
        corner_rates_N_per_m=[rate]*4,rail_heights_m=rails,
        sprung_loads=[dict(id='synthetic_body_reaction',vertical_down_N=30000,x_m=0,y_m=offset_y),dict(id='synthetic_sprung_truck_frame',vertical_down_N=10000,x_m=0,y_m=offset_y)],
        unsprung_axle_loads={ax:dict(vertical_down_N=4000,cg_y_m=0,additional_downward_roll_moment_Nm=0) for ax in ['front','rear']},
        constraints=dict(body_roll_K_Nm_per_rad=kr,body_roll_reference_slope=0,frame_warp=warp,warp_K_N_per_m=kw),
        extra_downward_slope_moments_Nm=dict(pitch=0,roll=0))

