    equations=dict(lower_seat='u(y_s)=(hR+hL)/2+y_s*(hR-hL)/(2*bw)',spring='F_i=k_i*(u_i-z_i), compression positive',normalized_unknowns='q=[h,a*theta,bs*phi,w] metres; omitw for rigid frame',basis='B_i=[1,x_i/a,y_i/bs,s_i]; omitlastcolumn forrigid',stiffness='C=diag(0,0,Kroll/bs^2,Kwarp) inN/m',load='f=[ΣW, (ΣW*x+M_pitch)/a, (ΣW*y+M_roll)/bs, 0]',solve='(B^T*K*B+C)*q=B^T*K*u-f+C*qref',axle_vertical='QR+QL=FR+FL+Wu',axle_moment='bw*(QR-QL)=bs*(FR-FL)+Wu*yu+Mu',rigid_pure_warp='u_i=s_i*d;deltaFi=s_i*k*d;deltaQi=(bs/bw)*deltaFi',compliant_pure_warp='w=4*k*d/(4*k+Kw);deltaFi=s_i*k*Kw/(4*k+Kw)*d',dimensionless_warp='eta=Kw/(4*k) for equalcornerrates, force multipliereta/(1+eta)',rail_warp_mapping='For front/rear meanheight0 and symmetriccrosslevels:rear_crosslevel-front_crosslevel=4*bw*d/bs. d isNOTrailcrosslevel.'),
